package zombie.core.skinnedmodel.model;public final class IsoObjectModelDrawer extends zombie.core.textures.TextureDraw.GenericDrawer{private final zombie.iso.SpriteModel spriteModel;private static final java.util.Map<ModelMesh,Model> resources=new java.util.IdentityHashMap<>();private final Model model;public IsoObjectModelDrawer(zombie.iso.SpriteModel m){this(m,null);}public IsoObjectModelDrawer(zombie.iso.SpriteModel m,ModelMesh mesh){spriteModel=m;model=resources.computeIfAbsent(mesh,k->{var value=new Model();value.mesh=k;return value;});}public void render(){throw new AssertionError("native render forbidden");}public void postRender(){throw new AssertionError("native cleanup forbidden");}}